Cc: Ville Syrjala <ville.syrjala@linux.intel.com>
Fixes: e93da0a0137b ("drm/i915/bxt: Sanitiy check the PHY lane power down status")
Bugzilla: https://bugs.freedesktop.org/show_bug.cgi?id=102777
Signed-off-by: Imre Deak <imre.deak@intel.com>
Reviewed-by: Rodrigo Vivi <rodrigo.vivi@intel.com>
Link: https://patchwork.freedesktop.org/patch/msgid/20171002135307.26117-1-imre.deak@intel.com

Here is the root cause:
The bug arises from the incorrect handling of the common lane power down flag in the DPIO PHY initialization process. After the initial enabling of the PHY, the flag is set only after the PHY is used for the first time. If the PHY is already powered on but the flag indicates it is powered down, subsequent checks may incorrectly disable the PHY, leading to a stuck state where the AUX power well cannot be enabled later.

Here is the patch:

 bool intel_ddi_get_hw_state(struct intel_encoder *encoder,
 			    enum pipe *pipe)
 {
 	struct drm_device *dev = encoder->base.dev;
 	struct drm_i915_private *dev_priv = to_i915(dev);
 	enum port port = intel_ddi_get_encoder_port(encoder);
 	u32 tmp;
 	int i;
 	bool ret;

 	if (!intel_display_power_get_if_enabled(dev_priv,
 						encoder->power_domain))
 		return false;

 	ret = false;

 	tmp = I915_READ(DDI_BUF_CTL(port));

 	if (!(tmp & DDI_BUF_CTL_ENABLE))
 		goto out;

 	if (port == PORT_A) {
 		tmp = I915_READ(TRANS_DDI_FUNC_CTL(TRANSCODER_EDP));

 		switch (tmp & TRANS_DDI_EDP_INPUT_MASK) {
 		case TRANS_DDI_EDP_INPUT_A_ON:
 		case TRANS_DDI_EDP_INPUT_A_ONOFF:
 			*pipe = PIPE_A;
 			break;
 		case TRANS_DDI_EDP_INPUT_B_ONOFF:
 			*pipe = PIPE_B;
 			break;
 		case TRANS_DDI_EDP_INPUT_C_ONOFF:
 			*pipe = PIPE_C;
 			break;
 		}

 		ret = true;

 		goto out;
 	}

 	for (i = TRANSCODER_A; i <= TRANSCODER_C; i++) {
 		tmp = I915_READ(TRANS_DDI_FUNC_CTL(i));

 		if ((tmp & TRANS_DDI_PORT_MASK) == TRANS_DDI_SELECT_PORT(port)) {
 			if ((tmp & TRANS_DDI_MODE_SELECT_MASK) ==
 			    TRANS_DDI_MODE_SELECT_DP_MST)
 				goto out;

 			*pipe = i;
 			ret = true;

 			goto out;
 		}
 	}

 	DRM_DEBUG_KMS("No pipe for ddi port %c found\n", port_name(port));

 out:
 	if (ret && IS_GEN9_LP(dev_priv)) {
 		tmp = I915_READ(BXT_PHY_CTL(port));
-		if ((tmp & (BXT_PHY_LANE_POWERDOWN_ACK |
+		if ((tmp & (BXT_PHY_CMNLANE_POWERDOWN_ACK |
+			    BXT_PHY_LANE_POWERDOWN_ACK |
 			    BXT_PHY_LANE_ENABLED)) != BXT_PHY_LANE_ENABLED)
 			DRM_ERROR("Port %c enabled but PHY powered down? "
 				  "(PHY_CTL %08x)\n", port_name(port), tmp);
 	}

 	intel_display_power_put(dev_priv, encoder->power_domain);

 	return ret;
 }



